const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { spawn } = require('node:child_process');
const { createInterface } = require('node:readline');
const { once } = require('node:events');
const { chromium, expect } = require(path.resolve('qtrace-ui/src-web/node_modules/@playwright/test'));

const root = process.cwd();
const folder = __dirname;
const web = path.join(root, 'qtrace-ui/src-web');
const scenarios = JSON.parse(fs.readFileSync(process.argv[2] ?? path.join(folder, 'capture-scenarios.json'), 'utf8'));
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const digest = (value) => crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex');
expect.configure({ timeout: 30_000 });

async function stop(child) {
  if (!child || child.exitCode !== null) return;
  const exited = once(child, 'exit');
  child.kill('SIGTERM');
  await Promise.race([exited, delay(3_000)]);
  if (child.exitCode === null) {
    child.kill('SIGKILL');
    await exited;
  }
}

async function verify(scenario, browser) {
  const directory = fs.mkdtempSync(path.join(folder, `${scenario.name}-browser-`));
  const record = { name: scenario.name, origin: scenario.origin, source_report: scenario.source_report, expected: scenario.expected, directory, checks: [], api_counts: {}, api_errors: [], page_errors: [], passed: false };
  let server, vite, context, page;
  const serverLog = fs.openSync(path.join(directory, 'server.stderr'), 'w');
  const viteLog = fs.openSync(path.join(directory, 'vite.log'), 'w');
  try {
    const token = crypto.randomBytes(16).toString('hex');
    server = spawn(path.join(root, 'qtrace-ui/target/release/e2e_server'), ['--fixture-root', scenario.fixture_root, '--xdg-root', path.join(directory, 'data'), '--token', token], { cwd: root, stdio: ['ignore', 'pipe', serverLog] });
    const ready = await Promise.race([
      new Promise((resolve, reject) => {
        const lines = createInterface({ input: server.stdout });
        lines.once('line', (line) => { try { resolve(JSON.parse(line)); } catch (error) { reject(error); } });
        server.once('exit', (code) => reject(new Error(`service exited before readiness: ${code}`)));
      }),
      delay(15_000).then(() => { throw new Error('service readiness timeout'); }),
    ]);
    vite = spawn(path.join(web, 'node_modules/.bin/vite'), ['--mode', 'e2e', '--port', '1421', '--strictPort'], { cwd: web, stdio: ['ignore', viteLog, viteLog], env: { ...process.env, VITE_E2E_URL: ready.url, VITE_E2E_TOKEN: ready.token } });
    let available = false;
    for (let attempt = 0; attempt < 150; attempt++) {
      if (vite.exitCode !== null) throw new Error(`Vite exited ${vite.exitCode}`);
      try { if ((await fetch('http://localhost:1421')).ok) { available = true; break; } } catch {}
      await delay(100);
    }
    if (!available) throw new Error('Vite readiness timeout');
    context = await browser.newContext({ viewport: { width: 1600, height: 1100 } });
    context.setDefaultTimeout(30_000);
    await context.tracing.start({ screenshots: true, snapshots: true, sources: true });
    page = await context.newPage();
    page.on('pageerror', (error) => record.page_errors.push(error.message));
    page.on('response', async (response) => {
      if (!response.url().startsWith(ready.url)) return;
      const command = new URL(response.url()).pathname.slice(1);
      record.api_counts[command] = (record.api_counts[command] ?? 0) + 1;
      if (!response.ok()) {
        try { record.api_errors.push({ command, status: response.status(), body: await response.json() }); }
        catch { record.api_errors.push({ command, status: response.status() }); }
      }
    });
    const api = (command, predicate = () => true) => page.waitForResponse(async (response) => {
      if (!response.url().endsWith('/' + command)) return false;
      return predicate(await response.json());
    }, { timeout: 60_000 }).then(async (response) => {
      const body = await response.json();
      if (!response.ok() || !Object.hasOwn(body, 'ok')) throw new Error(`${command}: ${JSON.stringify(body)}`);
      return body.ok;
    });
    const act = async (command, action, predicate) => {
      const answer = api(command, predicate);
      await action();
      return answer;
    };
    const apply = (kind = '') => act('query_timeline', async () => {
      await page.getByLabel('Kind', { exact: true }).fill(kind);
      await page.getByRole('button', { name: 'Apply filters', exact: true }).click();
    });
    const results = () => page.getByRole('region', { name: 'Search results', exact: true });
    const selectFirst = async (memory = false) => {
      const pending = [api('get_event_detail'), api('get_register_state'), api('get_call_tree')];
      if (memory) pending.push(api('get_memory_state'), api('get_memory_history'));
      await results().getByRole('listitem').first().getByRole('button').click();
      const values = await Promise.all(pending);
      expect(values[1].before).toHaveLength(34);
      expect(values[1].after).toHaveLength(34);
      expect(values[2].nodes.length).toBeLessThanOrEqual(100);
      if (memory) {
        expect(values[3].key).toEqual(values[0].key);
        expect(values[4].length).toBeLessThanOrEqual(2_000);
        await expect(page.getByRole('region', { name: 'Memory', exact: true })).not.toContainText('unsupported');
      }
      await expect(page.getByRole('alert')).toHaveCount(0);
      return values;
    };
    await page.goto('http://localhost:1421');
    const opened = await act('pick_and_open_session', () => page.getByRole('button', { name: 'Open session', exact: true }).click());
    expect(opened.artifacts).toHaveLength(1);
    expect(opened.artifacts[0].event_count).toBe(scenario.expected.event_count);
    const artifact = opened.artifacts[0];
    record.opened = { name: artifact.name, events: artifact.event_count, tids: artifact.tids, completeness_rows: artifact.completeness.length, context: opened.context };
    await expect(page.getByRole('heading', { name: /^Workspace / })).toBeVisible();
    record.checks.push('report context and real artifact count');

    const first = await apply();
    expect(first.exact_total).toBe(true);
    expect(first.total).toBe(scenario.expected.event_count);
    expect(first.rows.length).toBeLessThanOrEqual(2_000);
    expect(first.rows[0].key.artifact_sha256).toBe(scenario.expected.sha256);
    await expect(page.getByRole('grid', { name: 'Visible trace rows' })).toBeVisible();
    record.first_page_sha256 = digest(first.rows);
    if (first.total > 2_000) {
      const second = await act('query_timeline', () => results().getByRole('button', { name: 'Next results page', exact: true }).click());
      const keys = new Set(first.rows.map((row) => JSON.stringify(row.key)));
      expect(second.rows.some((row) => keys.has(JSON.stringify(row.key)))).toBe(false);
      await expect(results()).toContainText('Page 2 of');
      const previous = await act('query_timeline', () => results().getByRole('button', { name: 'Previous results page', exact: true }).click());
      expect(previous.rows).toEqual(first.rows);
      record.checks.push('real result pages next/previous without duplicate keys');
      const lastPending = api('query_timeline', (body) => body.ok?.total === first.total && body.ok.next_cursor === null);
      await page.getByRole('region', { name: 'Timeline', exact: true }).evaluate((element, total) => {
        element.style.height = '320px'; element.scrollTop = (total - 10) * 24;
        element.dispatchEvent(new Event('scroll', { bubbles: true }));
      }, first.total);
      const last = await lastPending;
      expect(last.rows.length).toBeLessThanOrEqual(2_000);
      record.last_page_sha256 = digest(last.rows);
      record.checks.push('distant viewport reaches final real timeline page');
      await page.getByRole('region', { name: 'Timeline', exact: true }).evaluate((element) => { element.scrollTop = 0; element.dispatchEvent(new Event('scroll', { bubbles: true })); });
    }
    record.checks.push('bounded real timeline and exact total');

    const instructions = await apply('instruction');
    expect(instructions.total).toBe(scenario.expected.event_counts.instruction);
    expect(instructions.rows.every((row) => row.kind === 'instruction')).toBe(true);
    const selected = await selectFirst();
    record.instruction = { source_row: selected[0].row, key: selected[0].key, register_sha256: digest(selected[1]), call_tree_nodes: selected[2].nodes.length };
    record.checks.push('instruction filter, real detail, 34-cell register replay and call tree');
    const comment = `browser acceptance ${scenario.name}`;
    await page.getByLabel('Comment', { exact: true }).fill(comment);
    await act('upsert_annotation', () => page.getByRole('button', { name: 'Save', exact: true }).click());
    await expect(page.getByText(`Committed: ${comment}`, { exact: true })).toBeVisible();
    await page.getByLabel('Highlight', { exact: true }).fill('acceptance');
    await act('upsert_highlight', () => page.getByRole('button', { name: 'Save highlight', exact: true }).click());

    const tid = selected[0].key.tid;
    if (tid !== null) {
      const filtered = await act('query_timeline', () => page.getByRole('button', { name: `TID ${tid}`, exact: true }).click());
      expect(filtered.rows.every((row) => row.key.tid === tid)).toBe(true);
      record.checks.push('real thread filter');
      await page.getByLabel('TID', { exact: true }).fill('');
    }
    const memoryPage = await apply('memory');
    expect(memoryPage.total).toBe(scenario.expected.event_counts.memory);
    const memory = await selectFirst(true);
    record.memory = { source_row: memory[0].row, state_sha256: digest(memory[3]), history_rows: memory[4].length };
    record.checks.push('real memory state and history without response-row budget errors');
    await page.screenshot({ path: path.join(directory, 'memory.png') });

    await page.getByLabel('Sequence', { exact: true }).fill('18446744073709551614:18446744073709551615');
    const empty = await apply('instruction');
    expect(empty.total).toBe(0);
    await expect(results()).toContainText('No rows on this page');
    record.checks.push('empty results');
    await page.getByLabel('Sequence', { exact: true }).fill('');
    await apply('instruction');
    await selectFirst();
    await expect(page.getByLabel('Comment', { exact: true })).toHaveValue(comment);
    await expect(page.getByLabel('Highlight', { exact: true })).toHaveValue('acceptance');
    await page.screenshot({ path: path.join(directory, 'instruction.png') });
    await act('close_workspace', () => page.getByRole('button', { name: 'Close', exact: true }).click());
    const restarted = await fetch(`${ready.url}/restart_service`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: '{}' });
    expect(restarted.ok).toBe(true);
    await page.reload();
    const reopened = await act('pick_and_open_session', () => page.getByRole('button', { name: 'Open session', exact: true }).click());
    expect(reopened.artifacts).toEqual(opened.artifacts);
    await apply('instruction');
    const reselected = await selectFirst();
    expect(reselected[1]).toEqual(selected[1]);
    await expect(page.getByLabel('Comment', { exact: true })).toHaveValue(comment);
    await expect(page.getByLabel('Highlight', { exact: true })).toHaveValue('acceptance');
    record.checks.push('service restart, cache reopen, equivalent registers and persistent comment/highlight');
    await page.screenshot({ path: path.join(directory, 'reopened.png') });
    expect(record.api_errors).toEqual([]);
    expect(record.page_errors).toEqual([]);
    record.passed = true;
  } catch (error) {
    record.error = String(error.stack ?? error);
    if (page) {
      try { await page.screenshot({ path: path.join(directory, 'failure.png') }); } catch {}
      try { record.visible_alerts = await page.getByRole('alert').allTextContents(); } catch {}
    }
  } finally {
    if (context) {
      try { await context.tracing.stop({ path: path.join(directory, 'trace.zip') }); } catch {}
      await context.close();
    }
    await stop(vite); await stop(server);
    fs.closeSync(serverLog); fs.closeSync(viteLog);
    fs.writeFileSync(path.join(directory, 'result.json'), JSON.stringify(record, null, 2) + '\n');
  }
  return record;
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const report = { chromium: browser.version(), method: 'Actual Chromium UI and Rust production service behind the existing authenticated E2E loopback transport; no response mocks or product-code changes.', scenarios: [] };
  try {
    for (const scenario of scenarios) {
      const result = await verify(scenario, browser);
      report.scenarios.push(result);
      console.log(JSON.stringify({ name: result.name, passed: result.passed, checks: result.checks, error: result.error, directory: result.directory }));
    }
  } finally {
    await browser.close();
    fs.writeFileSync(path.join(folder, 'browser-captures-result.json'), JSON.stringify(report, null, 2) + '\n');
  }
  if (report.scenarios.some((item) => !item.passed)) process.exitCode = 1;
})().catch((error) => { console.error(error); process.exitCode = 1; });
